  String toString() {
    return (StringBuffer('InboxEnvelope(')
          ..write('envelopeId: $envelopeId, ')
          ..write('sequence: $sequence, ')
          ..write('envelopeCiphertext: $envelopeCiphertext, ')
          ..write('processingState: $processingState, ')
